use std::collections::BTreeSet;
use super::typed_determinism_support::{self,TypedCapabilityInput3,CanonicalCapabilityOutput1};
use bioprism_foundation::{PRECLINICAL_BOUNDARY,RESEARCH_CONTRACT_SCHEMA_VERSION};
use bioprism_ids::ContentHash;
use serde::{Deserialize,Serialize};
use serde_json::json;
use thiserror::Error;
pub const CONTENT_TYPE:&str="application/vnd.aurora.worldgen.typed-determinism-copilot-receipt+json";
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct DeterminismCopilotRequest{pub determinism_request:TypedCapabilityInput3,pub action_order:Vec<String>,pub action_budget:u64,pub dry_run:bool,pub signed_approval:bool,pub federation_approved:bool,pub boundary:String}
#[derive(Debug,Clone,PartialEq,Eq,Serialize,Deserialize)]pub struct DeterminismCopilotReceipt{pub schema_version:String,pub contract_version:String,pub feature_id:String,pub request_id:String,pub disposition:String,pub action_order:Vec<String>,pub admitted_action_order:Vec<String>,pub denied_action_order:Vec<String>,pub determinism_disposition:String,pub canonical_digest:ContentHash,pub copilot_digest:ContentHash,pub replay_identity:ContentHash,pub omissions:Vec<String>,pub uncertainty:Vec<String>,pub negative_evidence:Vec<String>,pub effect_receipts:Vec<String>,pub artifact:serde_json::Value,pub raw_data_local:bool,pub aggregate_only:bool,pub boundary:String}
#[derive(Debug,Error,Clone,PartialEq,Eq)]pub enum DeterminismCopilotError{#[error("invalid determinism copilot request: {0}")]Invalid(String),#[error("determinism qualification failed: {0}")]Release(String),#[error("determinism copilot artifact failed: {0}")]Artifact(String),#[error("invalid determinism copilot receipt: {0}")]Receipt(String)}
fn h(v:&ContentHash)->bool{v.as_str().len()==64&&v.as_str().bytes().all(|b|b.is_ascii_hexdigit())}fn o(v:&[String])->bool{v.windows(2).all(|p|p[0]<p[1])}
impl DeterminismCopilotReceipt{pub fn validate(&self)->Result<(),DeterminismCopilotError>{if self.schema_version!=RESEARCH_CONTRACT_SCHEMA_VERSION||self.boundary!=PRECLINICAL_BOUNDARY||self.artifact.get("boundary").and_then(|v|v.as_str())!=Some(PRECLINICAL_BOUNDARY)||self.artifact.get("content_type").and_then(|v|v.as_str())!=Some(CONTENT_TYPE)||!self.raw_data_local||!self.aggregate_only||self.action_order.is_empty()||![&self.canonical_digest,&self.copilot_digest,&self.replay_identity].into_iter().all(h){return Err(DeterminismCopilotError::Receipt("determinism copilot identity or digest is incomplete".into()));}for v in [&self.action_order,&self.admitted_action_order,&self.denied_action_order,&self.omissions,&self.uncertainty,&self.negative_evidence,&self.effect_receipts]{if !o(v){return Err(DeterminismCopilotError::Receipt("determinism copilot vectors are not canonical".into()));}}let ids=self.action_order.iter().cloned().collect::<BTreeSet<_>>();let p=self.admitted_action_order.iter().chain(&self.denied_action_order).cloned().collect::<BTreeSet<_>>();if ids!=p||self.artifact.get("content_hash").and_then(|v|v.as_str())!=Some(self.copilot_digest.as_str()){return Err(DeterminismCopilotError::Receipt("determinism copilot actions do not partition".into()));}Ok(())}}
pub fn manifest(feature_id:&str,version:&str,scale:&str)->serde_json::Value{json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"capability_id":feature_id,"version":version,"owner_crate":"worldgen","consumers":["imaging core scientist","determinism operator","research program lead"],"behavior":format!("run approval-bounded determinism actions for {scale}"),"value":"turns qualified statistical evidence into a replayable copilot decision without hidden effects","input_schema":"DeterminismCopilotRequest1@1","output_schema":"DeterminismCopilotReceipt1@1","effects":["invoke:bounded-determinism-tool","block:unsafe-determinism"],"permissions":["invoke:declared-determinism-tool"],"determinism":"byte_stable","autonomy_tier":"A1","boundary":PRECLINICAL_BOUNDARY})}
pub fn run(r:&DeterminismCopilotRequest,feature_id:&str,version:&str,_scale:&str,require_approval:bool,_federation:bool)->Result<DeterminismCopilotReceipt,DeterminismCopilotError>{if r.boundary!=PRECLINICAL_BOUNDARY||r.action_order.is_empty()||r.action_order!={let mut x=r.action_order.clone();x.sort();x.dedup();x}||r.action_budget==0||!r.determinism_request.raw_data_local||!r.determinism_request.federated_summary_only{return Err(DeterminismCopilotError::Invalid("determinism copilot request is invalid".into()))}let determinism=typed_determinism_support::qualify(&r.determinism_request,feature_id,version).map_err(|e|DeterminismCopilotError::Release(e.to_string()))?;let mut omissions=determinism.omissions.clone();let approved=!require_approval||r.signed_approval;if !approved{omissions.push("copilot:approval-missing".into())}if r.dry_run{omissions.push("copilot:dry-run-no-effect".into())}if r.action_order.len()as u64>r.action_budget{omissions.push("copilot:action-budget-exceeded".into())}omissions.sort();omissions.dedup();let safe=determinism.disposition=="qualified"&&approved&&r.action_order.len()as u64<=r.action_budget;let disposition=if safe{"qualified"}else if determinism.disposition=="blocked"||!approved{"blocked"}else{"partial"};let admitted=if safe{r.action_order.clone()}else{Vec::new()};let denied=if safe{Vec::new()}else{r.action_order.clone()};let effects=if disposition=="blocked"{vec!["block:unsafe-determinism".into()]}else{vec![format!("invoke:bounded-determinism-tool:{}",determinism.canonical_digest)]};let payload=json!({"schema_version":RESEARCH_CONTRACT_SCHEMA_VERSION,"contract_version":version,"feature_id":feature_id,"request_id":r.determinism_request.request_id,"disposition":disposition,"action_order":r.action_order,"admitted_action_order":admitted,"denied_action_order":denied,"determinism_disposition":determinism.disposition,"canonical_digest":determinism.canonical_digest,"replay_identity":determinism.replay_identity,"omissions":omissions,"uncertainty":determinism.uncertainty,"negative_evidence":determinism.negative_evidence,"effect_receipts":effects,"raw_data_local":true,"aggregate_only":true,"boundary":PRECLINICAL_BOUNDARY});let d=ContentHash::of_value(&payload).map_err(|e|DeterminismCopilotError::Artifact(e.to_string()))?;let out=DeterminismCopilotReceipt{schema_version:RESEARCH_CONTRACT_SCHEMA_VERSION.into(),contract_version:version.into(),feature_id:feature_id.into(),request_id:r.determinism_request.request_id.clone(),disposition:disposition.into(),action_order:r.action_order.clone(),admitted_action_order:admitted,denied_action_order:denied,determinism_disposition:determinism.disposition,canonical_digest:determinism.canonical_digest,copilot_digest:d.clone(),replay_identity:determinism.replay_identity,omissions:payload["omissions"].as_array().unwrap().iter().map(|v|v.as_str().unwrap().into()).collect(),uncertainty:determinism.uncertainty,negative_evidence:determinism.negative_evidence,effect_receipts:effects,artifact:json!({"content_type":CONTENT_TYPE,"content_hash":d,"boundary":PRECLINICAL_BOUNDARY}),raw_data_local:true,aggregate_only:true,boundary:PRECLINICAL_BOUNDARY.into()};out.validate()?;Ok(out)}
